from datetime import datetime

def parse_dt(s):
    return datetime.fromisoformat(s.replace('Z','+00:00'))

# Collect all song_ids from the three libraries
song_ids = set()

# 1) Song library
page_index = 0
page_limit = 20
while True:
    page = apis.spotify.show_song_library(access_token=access_token, page_index=page_index, page_limit=page_limit)
    print('song_library page', page_index, 'len', len(page))
    if not page:
        break
    for it in page:
        song_ids.add(it['song_id'])
    page_index += 1

print('unique song_ids after song_library', len(song_ids))

# 2) Album library
page_index = 0
while True:
    page = apis.spotify.show_album_library(access_token=access_token, page_index=page_index, page_limit=page_limit)
    print('album_library page', page_index, 'len', len(page))
    if not page:
        break
    for album in page:
        for sid in album.get('song_ids', []) or []:
            song_ids.add(sid)
    page_index += 1

print('unique song_ids after album_library', len(song_ids))

# 3) Playlist library (both private and public? API has is_public param; default likely both?)
# We'll call twice: is_public=None (default) might already return both; but since spec says whether to show public/private,
# we'll attempt with is_public=None once, and if API errors we handle by trying True/False.

# First try default (omit is_public by passing None)
page_index = 0
try:
    while True:
        page = apis.spotify.show_playlist_library(access_token=access_token, is_public=None, page_index=page_index, page_limit=page_limit)
        print('playlist_library default is_public=None page', page_index, 'len', len(page))
        if not page:
            break
        for pl in page:
            for sid in pl.get('song_ids', []) or []:
                song_ids.add(sid)
        page_index += 1
except Exception as e:
    print('default playlist_library call failed', e)

    for is_public in [True, False]:
        page_index = 0
        while True:
            page = apis.spotify.show_playlist_library(access_token=access_token, is_public=is_public, page_index=page_index, page_limit=page_limit)
            print('playlist_library is_public', is_public, 'page', page_index, 'len', len(page))
            if not page:
                break
            for pl in page:
                for sid in pl.get('song_ids', []) or []:
                    song_ids.add(sid)
            page_index += 1

print('unique song_ids after playlist_library', len(song_ids))

# sanity: show a few ids
print('sample song_ids', sorted(list(song_ids))[:10])

